/// The image for `product`, or `None` for a category without images.
pub fn product_image(product: &Product) -> Option<Asset> {
    let (_, variants) = IMAGES
        .iter()
        .find(|(slug, _)| *slug == product.category_slug)?;
    Some(variants[product.id as usize % VARIANTS])
}

/// Resolves the product images to placeholder URLs, so views that render
/// them work in tests without a bundle from `topcoat asset bundle`.
#[cfg(test)]
pub fn test_asset_config() -> topcoat::asset::AssetConfig {
    use topcoat::asset::{AssetConfig, MANIFEST_VERSION, Manifest, ManifestEntry};

    let assets = IMAGES
        .iter()
        .flat_map(|(slug, variants)| {
            variants
                .iter()
                .enumerate()
                .map(move |(index, asset)| ManifestEntry {
                    id: asset.id(),
                    file: format!("{slug}-{}.jpg", index + 1),
                    hash: String::new(),
                    content_type: "image/jpeg".to_owned(),
                })
        })
        .collect();
    AssetConfig::hosted_at(
        "https://assets.test",
        Manifest {
            version: MANIFEST_VERSION,
            assets,
        },
    )
}

#[cfg(test)]
mod tests {
    use std::{collections::BTreeSet, path::Path};

    use super::*;
    use crate::catalog::Catalog;

    #[test]
    fn every_category_has_images() {
        let catalog = Catalog::load();
        for category in catalog.categories() {
            assert!(
                IMAGES.iter().any(|(slug, _)| *slug == category.slug),
                "no images for {}",
                category.slug
            );
        }
    }

    /// The table must list exactly the files the generator wrote.
    #[test]
    fn table_matches_generated_files() {
        let dir = Path::new(env!("CARGO_MANIFEST_DIR")).join("../data/images");
        let on_disk: BTreeSet<String> = std::fs::read_dir(dir)
            .unwrap()
            .map(|entry| entry.unwrap().file_name().into_string().unwrap())
            .filter(|name| {
                Path::new(name)
                    .extension()
                    .is_some_and(|ext| ext.eq_ignore_ascii_case("jpg"))
            })
            .collect();
        let declared: BTreeSet<String> = IMAGES
            .iter()
            .flat_map(|(slug, _)| (1..=VARIANTS).map(move |n| format!("{slug}-{n}.jpg")))
            .collect();
        assert_eq!(on_disk, declared);
    }

    #[test]
    fn products_pick_a_variant_by_id() {
        let catalog = Catalog::load();
        let config = test_asset_config();
        let product = catalog.get(1).unwrap();
        let url = config.resolve(product_image(product).unwrap());
        let expected = format!("{}-{}.jpg", product.category_slug, 1 % VARIANTS + 1);
        assert!(url.ends_with(&expected), "{url} should end with {expected}");
    }
}
